class Solution {
public:
    long long countKFreeSubsets(vector<int>& nums, int k) {
        unordered_map<int, vector<int>> chains;
        for (int x : nums) chains[x % k].push_back(x);
        long long ans = 1;
        for (auto& [r, vals] : chains) {
            sort(vals.begin(), vals.end());
            long long take = 0, skip = 1;
            int prev = INT_MIN;
            bool has = false;
            for (int v : vals) {
                long long nt = (has && v - prev == k) ? skip : take + skip;
                long long ns = take + skip;
                take = nt; skip = ns;
                prev = v; has = true;
            }
            ans *= take + skip;
        }
        return ans;
    }
};

