class Solution {
    public long countKFreeSubsets(int[] nums, int k) {
        Map<Integer, List<Integer>> chains = new HashMap<>();
        for (int x : nums) chains.computeIfAbsent(x % k, z -> new ArrayList<>()).add(x);
        long ans = 1;
        for (List<Integer> vals : chains.values()) {
            Collections.sort(vals);
            long take = 0, skip = 1;
            int prev = Integer.MIN_VALUE;
            boolean has = false;
            for (int v : vals) {
                long nt = (has && v - prev == k) ? skip : take + skip;
                long ns = take + skip;
                take = nt; skip = ns;
                prev = v; has = true;
            }
            ans *= take + skip;
        }
        return ans;
    }
}

