var countKFreeSubsets = function(nums, k) {
    const chains = new Map();
    for (const x of nums) {
        const r = ((x % k) + k) % k;
        if (!chains.has(r)) chains.set(r, []);
        chains.get(r).push(x);
    }
    let ans = 1;
    for (const vals of chains.values()) {
        vals.sort((a, b) => a - b);
        let take = 0, skip = 1, prev = null;
        for (const v of vals) {
            const nt = (prev !== null && v - prev === k) ? skip : take + skip;
            const ns = take + skip;
            take = nt; skip = ns;
            prev = v;
        }
        ans *= take + skip;
    }
    return ans;
};
